D[3730]={"^|cffffffffPrimal Infusion|r now increases affected targets healing received from |cFFFFFFFFHand of the Earthmother|r by an additional (.-)%%%.%s*$","|cffffffffInfusão Primeva|r agora aumenta a cura recebida pelos alvos afetados de |cFFFFFFFFMão da Mãe Terra|r em mais {{1}}%."}
