T[329]={"^Stoneslam powers up between uses faster, and being hit may speed it up even more%. Fully empowered Stoneslams grant Earth's Rage%.|r%s*$","Golpe de Pedra acumula poder mais rapidamente entre os usos, e receber golpes pode acelerar ainda mais esse processo. Golpes de Pedra totalmente fortalecidos concedem Fúria da Terra.|r"}
T[331]={"^Taking (.-) Nature Damage every (.-) sec%.%s*$","Recebe {{1}} de dano de Natureza a cada {{2}} s."}
T[375]={"^Reduces your damage taken by (.-)%%%. Melee attackers will suffer Nature damage when striking you%.%s*$","Reduz seu dano recebido em {{1}}%. Os atacantes corpo a corpo sofrerão dano de Natureza ao atingir você."}
T[376]={"^Reduces your damage taken%. Melee attackers will suffer Nature damage when striking you%.%s*$","Reduz seu dano recebido. Os atacantes corpo a corpo sofrerão danos de Natureza ao atingir você."}
T[442]={"^Deals (.-) Nature damage every (.-) sec%. Movement speed reduced by (.-)%%%.\n\nAt the end of the duration, you will be knocked into the air%.%s*$","Causa {{1}} de dano de Natureza a cada {{2}} s. Velocidade de movimento reduzida em {{3}}%.\n\nAo final da duração, você é lançado ao ar."}
T[461]={"^Dealing (.-) Physical damage every (.-) sec%.%s*$","Causa {{1}} de dano Físico a cada {{2}} s."}
T[564]={"^Using |cffffffffRuptured Earth|r, |cffffffffStonebreaker|r, |cffffffffEarthspine|r and |cffffffffPrimal Charge|r now slow the movement speed of affected enemies by (.-)%% and reduce their Armor by (.-)%% for (.-)%.%s*$","Usando |cffffffffTerra Rompida|r, |cffffffffQuebra-pedra|r, |cffffffffEspinha da Terra|r e |cffffffffPrimal Charge|r agora desacelera velocidade de movimento dos inimigos afetados em {{1}}% e reduz sua armadura em {{2}}% durante {{3}}."}
T[578]={"^Increases the range of |cffffffffStoneslam|r by (.-) yds, and increases the mana it regenerates by (.-)%%%.%s*$","Aumenta o alcance de |cffffffffImpacto de Pedra|r em {{1}} m, e aumenta a regeneração de mana que gera em {{2}}%."}
T[1141]={"^|cFFFFFFFFHand of the Earthmother|r  increases the critical strike chance of |cFFFFFFFFMending Growth|r  by (.-)%%, stacking up to (.-) times%.%s*$","|cFFFFFFFFMão da Mãe Terra|r aumenta a chance de acerto crítico de |cFFFFFFFFCrecimenta curativo|r em {{1}}%, acumulando-se até {{2}} vezes."}
T[1142]={"^Increases the healing of |cffffffffHand of The Earthmother|r and |cffffffffFlourishing Growth|r by (.-)%%%.%s*$","Aumenta em {{1}}% a cura de |cffffffffMão da Mãe Terra|r e |cffffffffCrescimento Florescente|r."}
T[1143]={"^Reduces the cooldown of |cffffffffPrimal Pulse|r by (.-) sec and increases its healing by (.-)%%%.%s*$","Reduzir a recarga de |cffffffffPulso Primevo|r em {{1}} s e aumentar sua cura em {{2}}%"}
T[1145]={"^Reduces the cooldown of |cffffffffPrimal Wave|r by (.-) sec and increases its healing by (.-)%%%.%s*$","Reduzir a recarga de |cffffffffOla Primal|r em {{1}} s e aumentar sua cura em {{2}}%"}
T[1149]={"^Damage dealt by |cffffffffGeode Barrage|r and |cffffffffGeodes|r reduces the cooldown of |cffffffffHeart of Azeroth|r by (.-) sec%.%s*$","O dano causado por |cffffffffBarragem de Geodos|r e |cffffffffGeodos|r reduz a recarga de |cffffffffCoração de Azeroth|r em {{1}} s."}
T[1152]={"^Reduces the duration of movement impairing effects by (.-)%% and increases the effectiveness of |cffffffffBoon of the Wolf|r by (.-)%%%.%s*$","Reduz a duração dos efeitos que impedem o movimento em {{1}}% e aumenta a eficácia do |cffffffffBônus do lobo|r em {{2}}%."}
T[1153]={"^Increases the Rage generated by |cFFFFFFFFPrimal Charge|r by (.-) and generate (.-) Rage passively every (.-) sec%.%s*$","Aumenta a Fúria gerada por |cFFFFFFFFCarga Primal|r em {{1}} e gera {{2}} Fúria passivamente a cada {{3}} s."}
T[1154]={"^Reduces the cooldown of |cffffffffPrimal Shred|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffDilacerar Primevo|r em {{1}} s."}
T[1165]={"^Casting |cffffffffEarth's Embrace|r now stuns enemies within (.-) yds of the target for (.-)%.%s*$","Lançar |cffffffffAbraço da Terra|r agora atordoa os inimigos em um raio de {{1}} m do alvo por {{2}}."}
T[1166]={"^Reduces the cooldown of |cffffffffEarth's Embrace|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffAbraço da Terra|r em {{1}} s."}
T[1167]={"^Increases healing done by (.-)%%, and healing received by (.-)%%%.%s*$","Aumenta a cura realizada em {{1}}% e a recebida em {{2}}%."}
