T[14467]={"^Casting speed of Geode Barrage reduced by (.-)%%%. Stacks (.-) times%. Increases the critical strike chance of Earthspine, Fracture, and Earthshard by (.-)%%\n\nAdditional applications do not refresh duration%.%s*$","A velocidade de lançamento de Barragem de Geodos é reduzida em {{1}}%. Acumula até {{2}} vezes. A chance de acerto crítico de Espinho Terrestre, Fratura e Fragmento Terrestre aumenta em {{3}}%.\n\nAplicações adicionais não renovam a duração."}
T[14468]={"^Casting speed of Geode Barrage reduced by (.-)%%%. Stacks (.-) times%.\n\nAdditional applications do not refresh duration%.%s*$","A velocidade de lançamento de Bala de Geodo é reduzida em {{1}}%. Acumula {{2}} vezes.\n\nAs aplicações adicionais não renovam a duração."}
T[14616]={"^|cffffffffPrimordial Blast|r generates 3 |cffffffffInscribed Runes|r%.%s*$","|cffffffffExplosão Primal|r gera 3 |cffffffffRunas inscritas|r."}
T[14618]={"^Reduces the cast time of |cffffffffPrimordial Blast|r by 0%.5 sec%.%s*$","Reduz o tempo de lançamento de |cffffffffExplosão Primal|r em 0,5 s."}
T[14676]={"^Reduces the rage cost of |cffffffffHand of The Earthmother|r by (.-)%.%s*$","Reduz o custo de raiva de |cffffffffMão da Mãe Terra|r em {{1}}."}
T[14682]={"^Your |cffffffffBoons|r restore (.-) health to affected allies, scaling with attack power and spell power%.%s*$","Seu |cffffffffBenefícios|r restauram {{1}} vida aos aliados afetados, escalando com o poder de ataque e o poder mágico."}
T[14683]={"^Gives successful blocks a 50%% chance to launch a Geode at the attacker, causing (.-) Nature damage and generating (.-) Rage%.\n\nCannot occur more than once every 5 sec%.%s*$","Bloqueios bem-sucedidos têm 50% de chance de lançar um Geodo contra o atacante, causando {{1}} de dano de Natureza e gerando {{2}} de Raiva.\n\nSó pode ocorrer uma vez a cada 5 s."}
T[14744]={"^Strength increased%.%s*$","Força aumentada."}
T[14792]={"^Melee abilities now heal 10 nearby allies, scaling with attack power%. \n\nCannot occur more than once every 5 sec%.%s*$","Agora as habilidades de corpo a corpo curam 10 aliados próximos, escalando com o poder de ataque.\n\nNão pode acontecer mais de uma vez a cada 5 s."}
T[15018]={"^Healing spells you cast grant you a damage absorption shield based on your attack power for (.-)%.\n\nCannot occur more than once every 8 sec%.%s*$","Os feitiços de cura que lances concedem a você uma avenida de absorção baseada em seu poder de ataque durante {{1}}.\n\nNão pode acontecer mais de uma vez a cada 8 s."}
T[15019]={"^At 5 stacks the Primalist's pet will deal additional damage to you%.%s*$","Com 5 acúmulos, o mascote do primitivista te causará dano adicional."}
T[17916]={"^Dealing damage with |cffffffffPrimordial Blast|r now reduces the affected target's armor by (.-)%% for (.-), stacking (.-) times%.%s*$","Causar dano com |cffffffffExplosão Primal|r agora reduz a armadura do alvo afetado em {{1}}% durante {{2}}, acumulando-se {{3}} vezes."}
T[18520]={"^At 3 stacks, you regenerate mana%.%s*$","Com 3 acúmulos, Você regenera mana."}
T[18577]={"^Movement speed slowed by (.-)%%%. Every (.-) sec, enemies inside take (.-) Nature Damage and are rooted for 3 sec%.%s*$","A velocidade de movimento é reduzida em {{1}}%. a cada {{2}} s, os inimigos dentro sofrem {{3}} dano de Natureza e restam imobilizados durante 3 s."}
T[18578]={"^Movement speed slowed by (.-)%%%. Every (.-) sec, enemies inside take (.-) Nature Damage and are rooted for 3 sec%.%s*$","A velocidade de movimento é reduzida em {{1}}%. a cada {{2}} s, os inimigos dentro sofrem {{3}} dano de Natureza e restam imobilizados durante 3 s."}
T[18583]={"^Movement speed increased by (.-)%%%. Every (.-) sec, allies inside are healed for (.-) and have 1 poison and disease effect dispelled from them%.%s*$","Velocidade de movimento aumentada em {{1}}%. A cada {{2}} s, aliados dentro da área são curados em {{3}} e têm 1 efeito de veneno ou doença dissipado."}
T[18584]={"^Movement speed increased by (.-)%%%. Every (.-) sec, allies inside are healed for (.-) and have 1 movement slowing effect dispelled from them%.%s*$","Velocidade de movimento aumentada em {{1}}%. A cada {{2}} s, aliados dentro da área são curados em {{3}} e têm 1 efeito de redução de movimento dissipado."}
T[18611]={"^Cleansing 1 disease and poison effect every (.-) sec%.%s*$","Limpa 1 doença e efeito de veneno a cada {{1}} s."}
T[18720]={"^Increases the healing of |cffffffffMending Growth|r by (.-)%% and reduces its casting time by 0%.25 sec%.%s*$","Aumenta a cura de |cffffffffCrecimenta curativo|r em {{1}}% e reduz seu tempo de lançamento em 0.25 s."}
T[19020]={"^Gives successful blocks a 50%% chance to launch a Geode at the attacker, causing (.-) Nature Damage and generating (.-) Rage%.\n\nCannot occur more than once every 5 sec%.%s*$","Bloqueios bem-sucedidos têm 50% de chance de lançar um Geodo contra o atacante, causando {{1}} de dano de Natureza e gerando {{2}} de Raiva.\n\nSó pode ocorrer uma vez a cada 5 s."}
T[19309]={"^At 2 stacks Geode Barrage transforms into Seismic Lance%.%s*$","Com 2 acúmulos, Barragem de Geodos se transforma em Lança Sísmica."}
T[19319]={"^Your next Primordial Blast unleashes a Shard of Conflagration for each stack of this effect%. Stacks up to 3 times%.\n\nShards of Conflagration deal Fire Damage, plus bonus Fire Damage for each consecutive Shard of Conflagration that hits the target%.%s*$","Sua próxima Explosão Primal libera um Fragmento de Conflagração para cada acúmulo deste efeito. Acumula até 3 vezes.\n\nFragmentos de Conflagração causam dano de Fogo e dano de Fogo adicional para cada Fragmento de Conflagração consecutivo que atingir o alvo."}
T[19320]={"^Your next Primordial Blast unleashes a Shard of Ice for each stack of this effect%. Stacks up to 3 times%.\n\nEach Shard causes Frost Damage and applies a stacking slow%.%s*$","Seu próximo Explosão primordial libertar um Fragmento de Gelo para cada acúmulo deste efeito. Acumula até 3 vezes.\n\nCada Fragmento causa dano de Gelo e aplica uma Desaceleração em pilha."}
T[19321]={"^Your next Primordial Blast unleashes a Shard of Arcana for each stack of this effect%. Stacks up to 3 times%.\n\nShards of Arcana deal Arcane Damage, and restore a portion of your Maximum Mana%.%s*$","Sua próxima Explosão Primeva libera um Fragmento Arcano para cada acúmulo deste efeito. Acumula até 3 vezes.\n\nOs Fragmentos Arcanos causam dano Arcano e restauram uma parte de sua mana máxima."}
T[19384]={"^Block Value increased by (.-)%%%. Successful Blocks reduce the Cast Time of your next Geode Barrage by (.-)%%, stacks up to 3 times%. In addition, all Geodes launched by your spells and abilities can bounce to up to (.-) enemies%.%s*$","Aumenta em {{1}}% seu valor de bloqueio. Bloqueios bem-sucedidos reduzem em {{2}}% o tempo de lançamento da sua próxima Barragem de Geodos, acumulando até 3 vezes. Além disso, todos os Geodos lançados por seus feitiços e habilidades podem ricochetear em até {{3}} inimigos."}
T[20981]={"^Increases your armor by (.-)%. \nIncreases your resistance to spells by (.-)%.%s*$","Aumenta sua armadura em {{1}}.\nAumenta sua resistência aos feitiços em {{2}}."}
T[25044]={"^(.-) damage per second%.%s*$","{{1}} p. de dano por segundo."}
